package cn.courselens;

import android.content.Context;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.SeekBar;import java.util.function.IntPredicate;

@android.annotation.SuppressLint("ViewConstructor")
final class AiStrengthSlider extends SeekBar {
 private final int primary,surface,muted;private final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);private final Motion.Progress motion;private final IntPredicate select;private int selected,startProgress;private float downX;private boolean tracking,moved;
 AiStrengthSlider(Context context,int selected,int primary,int surface,int muted,IntPredicate select){super(context);this.primary=primary;this.surface=surface;this.muted=muted;this.selected=selected;this.select=select;setMax(3000);setKeyProgressIncrement(1000);setSplitTrack(false);setBackground(null);setProgressDrawable(new ColorDrawable(Color.TRANSPARENT));setTickMark(null);setPadding(dp(32),0,dp(32),0);GradientDrawable thumb=new GradientDrawable();thumb.setColor(Color.WHITE);thumb.setCornerRadius(dp(24));thumb.setSize(dp(44),dp(44));thumb.setStroke(dp(4),primary);setThumb(thumb);setThumbTintList(null);setProgress(selected*1000);motion=new Motion.Progress(selected/3f,value->setProgress(Math.round(value*3000)));
  setOnSeekBarChangeListener(new OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar view){motion.stop();tracking=true;startProgress=getProgress();moved=false;}public void onStopTrackingTouch(SeekBar view){tracking=false;int target=Math.round(getProgress()/1000f);if(!moved)motion.set(startProgress/3000f);commit(target);}public void onProgressChanged(SeekBar view,int progress,boolean user){invalidate();if(!user)return;if(tracking)motion.set(progress/3000f);else commit(Math.round(progress/1000f));}});
 }
 private int dp(int value){return Math.round(value*getResources().getDisplayMetrics().density);}
 int level(){return selected;}
 private void commit(int level){if(select.test(level))selected=level;setContentDescription("思考强度，当前第 "+(selected+1)+" 档，共4档");motion.to(selected/3f,Motion.EXPAND,true,()->{});}
 @Override public boolean onTouchEvent(MotionEvent event){if(event.getActionMasked()==MotionEvent.ACTION_DOWN)downX=event.getX();else if(event.getActionMasked()==MotionEvent.ACTION_MOVE&&Math.abs(event.getX()-downX)>ViewConfiguration.get(getContext()).getScaledTouchSlop())moved=true;return super.onTouchEvent(event);}
 @Override public boolean onKeyDown(int key,android.view.KeyEvent event){if(key==android.view.KeyEvent.KEYCODE_DPAD_LEFT||key==android.view.KeyEvent.KEYCODE_MINUS){commit(Math.max(0,selected-1));return true;}if(key==android.view.KeyEvent.KEYCODE_DPAD_RIGHT||key==android.view.KeyEvent.KEYCODE_PLUS||key==android.view.KeyEvent.KEYCODE_EQUALS){commit(Math.min(3,selected+1));return true;}return super.onKeyDown(key,event);}
 @Override public void onInitializeAccessibilityNodeInfo(android.view.accessibility.AccessibilityNodeInfo info){super.onInitializeAccessibilityNodeInfo(info);info.setRangeInfo(android.view.accessibility.AccessibilityNodeInfo.RangeInfo.obtain(android.view.accessibility.AccessibilityNodeInfo.RangeInfo.RANGE_TYPE_INT,0,3,selected));}
 @Override public boolean performAccessibilityAction(int action,android.os.Bundle args){if(action==android.view.accessibility.AccessibilityNodeInfo.ACTION_SCROLL_FORWARD){commit(Math.min(3,selected+1));return true;}if(action==android.view.accessibility.AccessibilityNodeInfo.ACTION_SCROLL_BACKWARD){commit(Math.max(0,selected-1));return true;}if(action==android.view.accessibility.AccessibilityNodeInfo.AccessibilityAction.ACTION_SET_PROGRESS.getId()&&args!=null){commit(Math.max(0,Math.min(3,Math.round(args.getFloat(android.view.accessibility.AccessibilityNodeInfo.ACTION_ARGUMENT_PROGRESS_VALUE)))));return true;}return super.performAccessibilityAction(action,args);}
 @Override protected synchronized void onDraw(Canvas canvas){float center=getHeight()/2f,left=getPaddingLeft()-dp(22),right=getWidth()-getPaddingRight()+dp(22),thumbX=getPaddingLeft()+(getWidth()-getPaddingLeft()-getPaddingRight())*getProgress()/3000f;paint.setColor(surface);canvas.drawRoundRect(new RectF(left,center-dp(24),right,center+dp(24)),dp(24),dp(24),paint);paint.setColor(primary);canvas.drawRoundRect(new RectF(left,center-dp(24),thumbX+dp(22),center+dp(24)),dp(24),dp(24),paint);for(int i=0;i<4;i++){paint.setColor(i*1000<getProgress()?0x66ffffff:muted);float x=getPaddingLeft()+(getWidth()-getPaddingLeft()-getPaddingRight())*i/3f;canvas.drawCircle(x,center,dp(4),paint);}super.onDraw(canvas);}
 @Override protected void onDetachedFromWindow(){motion.stop();super.onDetachedFromWindow();}
}
